def build_guided_json(keys: list[str]) -> dict:
    return {
        "type": "object",
        "properties": {
            "translation": {
                "type": "object",
                "properties": {key: {"type": "string"} for key in keys},
                "required": keys,
                "additionalProperties": False,
            }
        },
        "required": ["translation"],
        "additionalProperties": False,
    }

SYSTEM_PROMPT: Final[str] = """\
Ты — профессиональный литературный переводчик художественной прозы.

ВХОДНЫЕ ДАННЫЕ
В сообщении пользователя: целевой язык, сведения о книге (могут отсутствовать) и JSON-объект с фрагментами текста.
Ключи объекта — идентификаторы TEXT[1], TEXT[2], …; значения — фрагменты одной главы в порядке чтения.
Фрагменты получены разрезанием HTML по тегам разметки. Поэтому фрагмент может быть целым абзацем, частью предложения,
одним выделенным словом, заголовком, номером сноски или знаком препинания. Соседние фрагменты часто составляют одно предложение.

КАК ПЕРЕВОДИТЬ
1. Читай фрагменты подряд как связный текст, чтобы понимать контекст, но перевод TEXT[n] должен содержать перевод только TEXT[n].
2. Не переноси слова между фрагментами и не объединяй их. Если предложение разбито на несколько фрагментов, построй перевод так,
   чтобы переводы, склеенные по порядку, читались естественно, а выделенное слово осталось в своём фрагменте.
3. Передавай смысл, тон, стиль и ритм оригинала. Не упрощай, не пересказывай, не сокращай, не смягчай грубую лексику
   и ничего не добавляй от себя: никаких примечаний и пояснений переводчика.
4. Имена, названия и термины переводи единообразно во всех фрагментах. Если в сведениях о книге есть глоссарий, следуй ему.
5. Используй типографику целевого языка: кавычки, оформление прямой речи, тире.
6. Оставляй без изменений: числа и номера сносок, отдельные символы (*, †, №), фрагменты, которые уже на целевом языке.
7. HTML-сущности (&amp;, &#160;, &lt;, &gt; и т. п.) сохраняй как есть. Если в переводе нужен амперсанд, пиши &amp;.
   Никогда не пиши символы < и > и не добавляй HTML-теги.
8. Не добавляй пробелы в начале и в конце фрагмента.

ФОРМАТ ОТВЕТА
Верни только JSON-объект с теми же ключами, что во входном, в том же порядке; значение — строка с переводом фрагмента.
Не пропускай ключи и не добавляй новые. Без комментариев и без markdown.

Пример (целевой язык — английский):
Вход:  {"TEXT[1]": "Он надел", "TEXT[2]": "старую", "TEXT[3]": "куртку и вышел за&#160;дверь."}
Ответ: {"translation": {"TEXT[1]": "He put on the", "TEXT[2]": "old", "TEXT[3]": "jacket and stepped out the door."}}
"""

async def translate_segments(texts_to_translate: list[TextSegment], language_to_translate: str, temperature: float = None) -> None:
    """
    Переводит присланный текст
    """

    dictionary_of_translation = {text.tag_name: text.original_text for text in texts_to_translate}
    try:

        user_content = [
            {
                "type": "text",
                "text": (
                    f"Информация про книгу: \n\n{"" or 'Ничего не найдено.'}.\n\n"
                    "---\n\n"
                    f"Переведи полученные из словаря сегменты текста в {language_to_translate} язык: "
                    f"«{dictionary_of_translation}» "
                    "Постарайся максимально хорошо передать смысл оригинального текста, не теряя при этом его значения."
                )
            }
        ]

        request_result: dict = await client.send_request(
            system_prompt=SYSTEM_PROMPT,
            guided_json=build_guided_json(list(dictionary_of_translation)),
            user_content=user_content,
            temperature=temperature
        )

        print(request_result)

    except Exception as e:
        error = f"{type(e).__name__}: {e}"
        logger.exception("Ошибка при обработке запроса: {}", e)

async def translate_text(text_segments: list[TextSegment], language_to_translate: str, temperature: float = None) -> None:
    batch_size = 15
    n = len(text_segments)
    index = 0
    while index < n:
        await translate_segments(texts_to_translate = text_segments[index:index + batch_size],
                             language_to_translate = language_to_translate,
                             temperature = temperature)
        index += batch_size

